package com.zerotrust.internalresource.controller; import com.zerotrust.internalresource.audit.*; import com.zerotrust.internalresource.dto.ApiResponse; import jakarta.servlet.http.HttpServletRequest; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api") public class ResourceController { private final GatewayAccessEvaluator gateway; public ResourceController(GatewayAccessEvaluator gateway){this.gateway=gateway;} @GetMapping("/files") public ApiResponse<List<Object>> files(HttpServletRequest r){return ApiResponse.success(List.of(),"file resource skeleton",trace(r));} @GetMapping("/devices") public ApiResponse<List<Object>> devices(HttpServletRequest r){return ApiResponse.success(List.of(),"device resource skeleton",trace(r));} @GetMapping("/test-resources/read") public ApiResponse<TestData> testRead(HttpServletRequest r){String trace=trace(r); return ApiResponse.success(new TestData("test-resource-read","GET",trace,r.getHeader("X-Session-Id")!=null,gateway.isGatewayAccess(r)),"test resource skeleton",trace);} private String trace(HttpServletRequest r){return (String)r.getAttribute(RequestContextFilter.TRACE_ID_ATTRIBUTE);} public record TestData(String resourceId,String action,String traceId,boolean sessionIdPresent,boolean gatewayAccess){} }